#!/usr/bin/env node
/**
 * Generates the part of the API reference that is already known.
 *
 * Path, method, surface and guard chain all live in `tuucho/docs/api/routes.json`,
 * derived from the running Express stack. Restating them by hand in
 * `tuucho/docs/api/` is work that can only go stale, so it is generated into
 * `tuucho/docs/api/09-reference.md` instead.
 *
 * The hand-written sections keep what a generator cannot know: why an endpoint
 * behaves the way it does, what a field means, which failure modes matter.
 * `--check` fails when the generated file is out of date.
 */
import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const root = resolve('.');
const docsRoot = resolve(root, '../../docs');
const inventoryPath = resolve(docsRoot, 'api/routes.json');
const outputPath = resolve(docsRoot, 'api/09-reference.md');

const inventory = JSON.parse(await readFile(inventoryPath, 'utf8'));
const features = JSON.parse(await readFile(resolve(docsRoot, 'features.json'), 'utf8'));

/** Which feature owns a route, by the module its handler lives in. */
const moduleToFeature = new Map();
for (const [name, entry] of Object.entries(features)) {
  if (name.startsWith('$')) continue;
  moduleToFeature.set(entry.module, name);
}
function featureOf(source) {
  if (!source) return '';
  for (const [modulePath, name] of moduleToFeature) {
    if (source.startsWith(`${modulePath}/`)) return name;
  }
  return '';
}

/** The guards that decide who may call a route, in the order they run. */
const AUTH_GUARDS = new Set([
  'requireAuth',
  'requireAdmin',
  'optionalAuth',
  'requireOpsToken',
  'rejectUnresolvedBearer',
  'requireSameOriginForCookieSession',
  'requireAccountCheckoutSession',
  'requireGuestCheckoutSession',
  'requireGiftCheckoutSession',
  'requireStaff',
]);

/** `requirePermission(orders/users)`: the section grant an `/admin` route needs. */
const isAuthGuard = (name) => AUTH_GUARDS.has(name) || name.startsWith('requirePermission(');

function accessOf(route, shared) {
  const guards = [...shared, ...route.middleware].filter(isAuthGuard);
  return guards.length > 0 ? guards.join(' + ') : 'public';
}

function table(routes, shared) {
  const rows = routes.map((route) => {
    const feature = featureOf(route.source);
    return `| \`${route.method}\` | \`${route.path}\` | ${accessOf(route, shared)} | ${feature ? `[${feature}](../features.json)` : ''} | \`${route.source ?? ''}\` |`;
  });
  return ['| Method | Path | Access | Feature | Handler |', '| --- | --- | --- | --- | --- |', ...rows].join('\n');
}

const generated = `# Route reference

<!-- Generated by \`npm run sync:api-reference\` from tuucho/docs/api/routes.json.
     Do not edit: \`npm run check:api-reference\` rejects a hand-edited copy.
     Behaviour, field meanings and failure modes are documented by hand in the
     other files in this directory; this one only answers what exists, where it
     is served from, and who may call it. -->

Every route this service serves, read from the composed Express app rather than
from the source. ${inventory.publicSurface.length} public and ${inventory.opsSurface.length} operations routes.

For what an endpoint *does*, read the hand-written section for its feature:
[admin](./01-admin.md), [auth](./02-auth.md), [account](./03-account.md),
[guest checkout](./04-guest-checkout.md), [contact and chat](./05-contact-chat.md),
[gallery](./06-gallery.md), [operations](./07-operation.md), [gift](./08-gift.md).

## Public surface

Applied to every public route: ${inventory.publicSurfaceMiddleware.map((name) => `\`${name}\``).join(', ')}.

${table(inventory.publicSurface, inventory.publicSurfaceMiddleware)}

## Operations surface

Loopback only, never mounted on the public app. Applied to every operations
route: ${inventory.opsSurfaceMiddleware.map((name) => `\`${name}\``).join(', ')}.

${table(inventory.opsSurface, inventory.opsSurfaceMiddleware)}
`;

if (process.argv.includes('--check')) {
  const current = await readFile(outputPath, 'utf8').catch(() => '');
  if (current !== generated) {
    console.error('API reference check failed: tuucho/docs/api/09-reference.md is out of date.');
    console.error('Run `npm run sync:api-reference` (after `npm run sync:routes` if a route changed).');
    process.exit(1);
  }
  console.log(
    `API reference check passed (${inventory.publicSurface.length + inventory.opsSurface.length} routes).`,
  );
  process.exit(0);
}

await writeFile(outputPath, generated);
console.log(
  `API reference written (${inventory.publicSurface.length} public, ${inventory.opsSurface.length} ops routes).`,
);
